qw.show_on_contact=Boolean(document.getElementById('qwShowContact')?.checked);
qw.show_price_estimate=Boolean(document.getElementById('qwShowPrice')?.checked);
qw.whatsapp_handoff=Boolean(document.getElementById('qwWaHandoff')?.checked);
qw.eyebrow=document.getElementById('qwEyebrow')?.value.trim()||'';
qw.currency=document.getElementById('qwCurrency')?.value.trim()||'₺';
