qw.heading_accent=document.getElementById('qwHeadingAcc')?.value.trim()||'';
qw.lead=document.getElementById('qwLead')?.value.trim()||'';
qw.submit_label=document.getElementById('qwSubmitLbl')?.value.trim()||'Teklif & Yol Haritasını Gönder';
const cats=[];
ROOT.querySelectorAll('[data-qw-cat-row]').forEach((row,idx)=>{
const title=row.querySelector('[data-f="title"]')?.value.trim()||'';
if(!title)return;
cats.push({
id:(qw.categories?.[idx]?.id)||('cat-'+(idx+1)),
icon:row.querySelector('[data-f="icon"]')?.value.trim()||'⚡',
title,
desc:row.querySelector('[data-f="desc"]')?.value.trim()||'',
min:Number(row.querySelector('[data-f="min"]')?.value||0),
max:Number(row.querySelector('[data-f="max"]')?.value||0)
});
});
qw.categories=cats;
const feats=[];
ROOT.querySelectorAll('[data-qw-feat-row]').forEach((row,idx)=>{
const title=row.querySelector('[data-f="title"]')?.value.trim()||'';
if(!title)return;
feats.push({
id:(qw.features?.[idx]?.id)||('ft-'+(idx+1)),
title,
desc:row.querySelector('[data-f="desc"]')?.value.trim()||'',
min:Number(row.querySelector('[data-f="min"]')?.value||0),
max:Number(row.querySelector('[data-f="max"]')?.value||0)
});
});
qw.features=feats;
